						.both(zh: "在 Claude 的 SendMessage 触达你这台机器之外的某个 session 之前，要求你明确批准；见「跨机器消息需要批准」。即使处于 bypassPermissions 模式也会出现批准提示。", en: "Require your explicit approval before Claude's SendMessage reaches one of your sessions beyond this machine; see Require approval for cross-machine messages. The approval prompt appears even in bypassPermissions mode.")
					),
					textField(
						"processWrapper", .both(zh: "processWrapper", en: "processWrapper"), "",
						.both(zh: "在 macOS 和 Linux 上，在 Claude Code 启动的后台进程前面放一个企业启动器命令。Claude Code 会把自己的命令行追加到启动器后面运行，所以启动器必须 exec 进入 Claude Code；见「在企业启动器后面运行 Claude Code」…", en: "On macOS and Linux, place a corporate launcher command in front of the background processes Claude Code starts. Claude Code runs the launcher with its own command line appended, so the launcher must exec into Claude Code; see Run Claude Code behind a corporate launcher for the…")
					),
					textField(
						"teammateMode", .both(zh: "teammateMode", en: "teammateMode"), "",
						.both(zh: "选择 Claude Code 在哪里显示 agent team 的队友：你的主终端窗格内，还是终端支持时的分屏。见「选择显示模式」。", en: "Choose where Claude Code shows agent team teammates: inside your main terminal pane, or in split panes when your terminal supports them. See Choose a display mode.")
					),
					jsonField(
						"worktree", .both(zh: "worktree", en: "worktree"),
						.both(zh: "配置 Claude Code 如何为 --worktree、EnterWorktree 工具以及隔离的 subagent 和后台 session 创建和管理 git worktree。", en: "Configure how Claude Code creates and manages git worktrees for --worktree, the EnterWorktree tool, and isolated subagents and background sessions.")
					),
					textField(
						"worktree.baseRef", .both(zh: "worktree.baseRef", en: "worktree.baseRef"), "",
						.both(zh: "选择新 worktree 从哪个 ref 分叉。'fresh' 从 origin/<默认分支> 分叉，得到与远端一致的干净工作树；'head' 从你当前的本地 HEAD 分叉，因此未推送的提交和功能分支状态都会出现在 worktree 里。", en: "Choose which ref new worktrees branch from. 'fresh' branches from origin/<default-branch> for a clean tree matching the remote; 'head' branches from your current local HEAD, so unpushed commits and feature-branch state are present in the worktree.")
					),
					textField(
						"worktree.bgIsolation", .both(zh: "worktree.bgIsolation", en: "worktree.bgIsolation"), "",
						.both(zh: "选择后台 session 如何隔离它们的文件修改。取值为 'worktree' 时，Claude Code 在 session 调用 EnterWorktree 之前阻止在主检出里使用 Edit 和 Write；取值为 'none' 时，后台任务直接修改工作副本。对于 git worktree…的仓库，设为 'none'。", en: "Choose how background sessions isolate their file edits. With 'worktree', Claude Code blocks Edit and Write in the main checkout until the session calls EnterWorktree; with 'none', background jobs edit the working copy directly. Set 'none' for a repository where git worktrees…")
					),
					listField(
						"worktree.sparsePaths", .both(zh: "worktree.sparsePaths", en: "worktree.sparsePaths"),
						.both(zh: "通过 git sparse-checkout 只检出每个 worktree 里列出的目录。Claude Code 只把这些目录和根级文件写到磁盘，在大型 monorepo 里更快；见「只检出你需要的目录」。", en: "Check out only the listed directories in each worktree through git sparse-checkout. Claude Code writes only those directories plus root-level files to disk, which is faster in large monorepos; see Check out only the directories you need.")
					),
					listField(
						"worktree.symlinkDirectories", .both(zh: "worktree.symlinkDirectories", en: "worktree.symlinkDirectories"),
						.both(zh: "把主仓库里的目录软链到每个 worktree，这样就不必在磁盘上重复占用大目录。", en: "Symlink directories from the main repository into each worktree so you don't duplicate large directories on disk.")
					),
				]
			),
