					),
					listField(
						"disabledMcpjsonServers", .both(zh: "disabledMcpjsonServers", en: "disabledMcpjsonServers"),
						.both(zh: "拒绝项目 .mcp.json 文件里定义的特定 server，使 Claude Code 永不连接它们、也不请求你批准。任何设置文件里的拒绝都会生效，包括签入仓库的项目 .claude/settings.json。", en: "Reject specific servers defined in a project's .mcp.json file so Claude Code never connects them or asks you to approve them. A rejection in any settings file applies, including a project .claude/settings.json checked into the repository.")
