					),
					listField(
						"enabledMcpjsonServers", .both(zh: "enabledMcpjsonServers", en: "enabledMcpjsonServers"),
						.both(zh: "批准项目 .mcp.json 文件里定义的特定 server，使 Claude Code 不经询问就连接它们。当你在批准对话框里批准某个 server 时，Claude Code 会把这个键写入 .claude/settings.local.json。", en: "Approve specific servers defined in project .mcp.json files so Claude Code connects them without asking. Claude Code writes this key to .claude/settings.local.json when you approve a server in the approval dialog.")
					),
				]
			),
			SettingsSection(
